        "test_file" => "tf",
        "test_proximity" => "test",
        "config_file" => "cfg",
        "config_dependency_intent" => "cfgdep",
        "dependency_manifest_intent" => "dep",
        "benchmark_evidence_file_intent" => "bench",
        "readme_evidence_file_intent" => "readme",
        "competitive_positioning_doc" => "comp",
        "docs_intent" => "doc",
